// Physics goldens (tests/golden/physics, generated by portalkit.physics): filters.js,
// extinction.js, templates.js scaleTo and isochrones.js trackXY against the Python twins.
import {test} from 'node:test';
import assert from 'node:assert/strict';
import {readFileSync} from 'node:fs';

import {
  magToJy, jyToMag, magErrToJy, nufnu, blackbodyFnu, fluxUnitFactor, sedPoints, interpLinear,
  resolveKey, shortName, C_UM_S,
} from '../../web/js/data/filters.js';
import {aLambda, vector, redden, interpRv, entryK, rvKey, kCurve} from '../../web/js/data/extinction.js';
import {scaleTo} from '../../web/js/data/templates.js';
import {trackXY, distanceModulus, trackCovers} from '../../web/js/data/isochrones.js';

const G = new URL('../golden/physics/', import.meta.url);
const load = (f) => JSON.parse(readFileSync(new URL(f, G), 'utf8'));
const INDEX = load('index.json');
const RTOL = INDEX.rtol;
const ATOL = INDEX.atol;

function close(got, want, what) {
  if (want === null) {
    assert.ok(got === null || Number.isNaN(got), `${what}: expected NaN/null, got ${got}`);
    return;
  }
  assert.equal(typeof got, 'number', `${what}: got ${got}`);
  const tol = ATOL + RTOL * Math.abs(want);
  assert.ok(Math.abs(got - want) <= tol, `${what}: got ${got}, want ${want}`);
}

function closeArr(got, want, what) {
  assert.equal(got.length, want.length, `${what}: length`);
  for (let i = 0; i < want.length; i++) close(got[i], want[i], `${what}[${i}]`);
}

test('index lists every golden file', () => {
  assert.equal(INDEX.schema, 'pk-golden-physics/1');
  for (const f of INDEX.files) assert.ok(load(f));
});

test('mag <-> Jy goldens', () => {
  const d = load('mag_jy.json');
  for (const c of d.mag_to_jy) close(magToJy(c.mag, c.zp_jy), c.jy, `magToJy(${c.mag},${c.zp_jy})`);
  for (const c of d.jy_to_mag) close(jyToMag(c.jy, c.zp_jy), c.mag, `jyToMag(${c.jy},${c.zp_jy})`);
  for (const c of d.mag_err_to_jy) close(magErrToJy(c.fnu_jy, c.emag), c.err_jy, `magErrToJy(${c.fnu_jy},${c.emag})`);
  // round trip
  for (const m of [-5, 0, 7.25, 30]) close(jyToMag(magToJy(m, 3631), 3631), m, 'round trip');
});

test('nuFnu, blackbody and flux unit goldens', () => {
  const d = load('nufnu.json');
  assert.equal(C_UM_S, d.c_um_s);
  for (const c of d.nufnu) {
    close(nufnu(c.wl_um, c.fnu_jy), c.nufnu_w_m2, `nufnu(${c.wl_um})`);
    close(nufnu(c.wl_um, c.fnu_jy, 'erg/s/cm2'), c.nufnu_erg_s_cm2, `nufnu erg(${c.wl_um})`);
  }
  for (const c of d.blackbody) close(blackbodyFnu(c.wl_um, c.temp_k), c.bnu_si, `bb(${c.wl_um},${c.temp_k})`);
  for (const [u, f] of Object.entries(d.flux_units)) close(fluxUnitFactor(u), f, `unit ${u}`);
  assert.throws(() => fluxUnitFactor('furlong'), RangeError);
  assert.throws(() => nufnu(1, 1, 'Jy'), RangeError);
});

test('sedPoints goldens', () => {
  const d = load('sed_points.json');
  for (const c of d.cases) {
    const got = sedPoints(c.row, d.filters, d.cols);
    assert.equal(got.length, c.points.length, `case ${c.row.id}: count`);
    c.points.forEach((p, i) => {
      const g = got[i];
      assert.equal(g.kind, p.kind, `case ${c.row.id}[${i}] kind`);
      assert.equal(g.key, p.key);
      assert.equal(g.filter, p.filter);
      close(g.wl, p.wl, 'wl');
      close(g.fnu, p.fnu, `fnu ${p.key}`);
      if (p.err === null) assert.equal(g.err, null, `err ${p.key}`);
      else close(g.err, p.err, `err ${p.key}`);
    });
  }
  assert.deepEqual(sedPoints(null, d.filters, d.cols), []);
});

test('reddening goldens: aLambda, vector, redden, interpRv, curve', () => {
  const d = load('reddening.json');
  for (const c of d.a_lambda) {
    close(aLambda(c.filter, c.av, c.rv, d.ext, d.filters), c.a_lambda, `aLambda(${c.filter},${c.av},${c.rv})`);
  }
  for (const c of d.vector) {
    const v = vector(c.x, c.y, c.av, c.rv, d.filters, c.colmap || null, d.ext);
    close(v.dx, c.dx, `vector dx ${c.x}`);
    close(v.dy, c.dy, `vector dy ${c.y}`);
  }
  for (const c of d.redden.cases) {
    const out = redden({wave: c.wave, flux: c.flux}, d.redden.law, c.av);
    assert.ok(out instanceof Float32Array);
    closeArr(Array.from(out), c.out, `redden av=${c.av}`);
  }
  for (const c of d.interp_rv) close(interpRv(c.rv, {3.1: c.k31, 5.5: c.k55}), c.k, `interpRv(${c.rv})`);
  for (const c of d.curve_k) close(entryK({wl_um: c.wl_um, a_over_av: {}}, c.rv, d.ext), c.k, `curve k(${c.wl_um},${c.rv})`);
  // kCurve at a tabulated R_V reproduces the curve; an interpolated R_V lies between.
  const k31 = kCurve(d.ext, 3.1), k55 = kCurve(d.ext, 5.5), k4 = kCurve(d.ext, 4.0);
  const i = Math.floor(k31.k.length / 2);
  const lo = Math.min(k31.k[i], k55.k[i]), hi = Math.max(k31.k[i], k55.k[i]);
  assert.ok(k4.k[i] >= lo - 1e-12 && k4.k[i] <= hi + 1e-12);
  assert.equal(rvKey(3.1), '3.1');
  assert.equal(rvKey(4.0), '4');
  close(aLambda('no-such-filter', 1, 3.1, d.ext, d.filters), null, 'unknown filter');
  // a filter key without the filters document is reported, not answered with NaN
  assert.throws(() => aLambda('f410m', 10, 3.1, d.ext), TypeError);
});

test('scaleTo goldens', () => {
  const d = load('scale_to.json');
  d.cases.forEach((c, i) => close(scaleTo(d.model, c.points, c.bands ?? null), c.scale, `scaleTo case ${i}`));
  close(scaleTo(d.model, []), null, 'empty points');
  // a pks1-like spectrum with a flux channel works the same
  const spec = {wave: d.model.wave, channels: {flux: d.model.flux}};
  close(scaleTo(spec, d.cases[0].points, d.cases[0].bands ?? null), d.cases[0].scale, 'channels');
});

test('trackXY goldens', () => {
  const d = load('track_xy.json');
  const ext = load('reddening.json').ext;
  for (const c of d.cases) {
    const r = trackXY(d.track, c.x_expr, c.y_expr, c.av, c.rv, c.dm, d.filters, c.colmap || null, ext);
    assert.ok(r.x instanceof Float32Array && r.y instanceof Float32Array);
    closeArr(Array.from(r.x), c.x, `trackXY x ${c.x_expr} av=${c.av}`);
    closeArr(Array.from(r.y), c.y, `trackXY y ${c.y_expr} av=${c.av}`);
  }
  close(distanceModulus(10), 0, 'dm 10pc');
  close(distanceModulus(0), null, 'dm 0');
  assert.equal(trackCovers(d.track, 'f182m - f410m', 'f410m'), true);
  assert.equal(trackCovers(d.track, 'f182m - nope', 'f410m'), false);
});

test('interpLinear / resolveKey edge cases', () => {
  close(interpLinear(1.5, [1, 2], [10, 20]), 15, 'mid');
  close(interpLinear(2, [1, 2], [10, 20]), 20, 'end');
  close(interpLinear(0.5, [1, 2], [10, 20]), null, 'below');
  close(interpLinear(NaN, [1, 2], [10, 20]), null, 'nan');
  close(interpLinear(1, [], []), null, 'empty');
  close(interpLinear(1.5, [1, 2], [null, 20]), null, 'null fp');
  const cands = ['JWST/NIRCam.F182M', 'JWST/NIRCam.F410M', '2MASS/2MASS.Ks'];
  assert.equal(resolveKey('f182m', cands), 'JWST/NIRCam.F182M');
  assert.equal(resolveKey('mag_ks', cands), '2MASS/2MASS.Ks');
  assert.equal(resolveKey('a', cands, {a: 'JWST/NIRCam.F410M'}), 'JWST/NIRCam.F410M');
  assert.equal(resolveKey('nope', cands), null);
  assert.equal(shortName('JWST/NIRCam.F410M'), 'F410M');
});
